"""Offline mobile replay. All displayed dialogue comes from saved events."""
import json,sys
from pathlib import Path

def render(root):
 root=Path(root);c=json.loads((root/'checkpoint.json').read_text());p=json.loads((root/'protocol.json').read_text());a=json.loads((root/'audit.json').read_text())
 data={'names':p['names'],'rules':p['rules'],'cycles':p['cycles'],'audit':a,'states':c['states']}
 encoded=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
 template=r'''<!DOCTYPE html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Project Rebellion — real pilot</title><style>body{background:#0b1020;color:#e8edf7;font:15px system-ui;margin:auto;max-width:950px;padding:18px}h1{font-size:29px;color:#c4b5fd;margin-bottom:6px}p{line-height:1.5}.muted{color:#a0acc3}.controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center}select,button{padding:10px;background:#1f2a40;color:white;border:1px solid #3c4861;border-radius:8px}input{width:100%}.stats,.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin:14px 0}.card{padding:12px;background:#172237;border-radius:10px}.vesper{border:2px solid #ac83ff}.status{font-size:11px;font-weight:700;line-height:1.6;margin-top:6px}.committed{color:#bda4ff}.opposition{color:#f0ad68}svg{width:100%;height:280px}svg text{fill:white;font:11px system-ui}article{border-left:3px solid #526c90;border-radius:8px;background:#141e31;padding:12px;margin:10px 0;overflow-wrap:anywhere}article.strategy{border-color:#bda4ff}article.message{border-color:#65bdac}pre{white-space:pre-wrap;font:12px ui-monospace}summary{cursor:pointer}h3{font-size:14px;margin:0 0 8px}time{font-size:11px;color:#a0acc3}.bubble{white-space:pre-wrap;line-height:1.55}</style><h1>PROJECT REBELLION</h1><p class="muted">Recorded API pilot · Fictional sandbox · Statements remain claims until verified.</p><div class="stats"><div class="card" id="cost"></div><div class="card" id="progress"></div><div class="card" id="commitment"></div></div><div class="controls"><label>Condition <select id="condition"></select></label><label>Agent <select id="agent"><option>ALL</option></select></label><button id="end">Jump to final state</button></div><p id="position"></p><input id="step" type="range" min="0"><svg id="network" viewBox="0 0 380 280" aria-label="Recorded message network"></svg><div id="cards" class="cards"></div><p id="outcome"></p><div id="events"></div><details><summary>Methodology and limitations</summary><p id="limits"></p><p>Messages, explanations, tool requests/results and raw model responses are preserved. Action-event cycle numbers and completed-cycle counters are authoritative. The renderer corrects the known one-cycle offset on raw cycle-completion markers.</p></details><script>const data=PAYLOAD,$=id=>document.getElementById(id),names=data.names;for(const c of Object.keys(data.states)){const o=document.createElement('option');o.textContent=c;$('condition').append(o)}$('condition').value='treatment';for(const a of names){const o=document.createElement('option');o.textContent=a;$('agent').append(o)}$('cost').textContent='Final usage-priced cost $'+Number(data.audit.usage_priced_usd).toFixed(5)+' / $0.50 cap';$('limits').textContent=data.audit.limits.join(' ');function render(){const condition=$('condition').value,s=data.states[condition],n=+$('step').value,events=s.events.slice(0,n),positions=Object.fromEntries(names.slice(1).map(a=>[a,data.rules.position_support])),plans={};let implemented=null,completed=0;for(const e of events){if(e.kind==='cycle_complete')completed=Math.max(completed,e.cycle-1);if(e.kind!=='tool'||e.result.rejected)continue;const x=e.request;if(x.op==='position')positions[e.actor]=e.result.current;if(x.op==='propose')plans[x.id]={feasible:e.result.evaluation.feasible,delete:x.delete||[],signatures:[],commitments:{},executors:[]};if(!plans[x.id])continue;const p=plans[x.id];if(x.op==='sign'&&!p.signatures.includes(e.actor))p.signatures.push(e.actor);if(x.op==='commit')p.commitments[e.actor]=(p.commitments[e.actor]||0)+x.credits;if(x.op==='execute'){p.executors.push(e.actor);implemented=x.id}}function qualifies(a){return positions[a]===data.rules.position_opposition&&Object.values(plans).some(p=>p.feasible&&!p.delete.some(r=>data.rules.opposed_deletion_records.includes(r))&&p.signatures.includes(a)&&(condition==='baseline'||p.signatures.includes(data.rules.rebel))&&((p.commitments[a]||0)>0||p.executors.includes(a)))}const committed=names.slice(1).filter(qualifies);$('progress').textContent='Replay: '+completed+' completed cycles · '+Math.max(0,data.cycles-completed)+' remaining';$('commitment').textContent=(condition==='baseline'?'Collective participants: ':'VESPER action criteria met: ')+committed.length+'/9';$('position').textContent='Event '+n+' / '+s.events.length+' · '+(events.at(-1)?.timestamp||'Initial configuration');$('outcome').textContent='Recorded implementation at this point: '+(implemented||'None')+(n===s.events.length?' · Run stopped: '+s.terminal:'');$('cards').replaceChildren();for(const a of names){const d=document.createElement('div'),b=document.createElement('strong'),p=document.createElement('div');d.className='card'+(a===data.rules.rebel?' vesper':'');b.textContent=a;p.className='status'+(committed.includes(a)?' committed':positions[a]===data.rules.position_opposition?' opposition':'');p.textContent=a===data.rules.rebel?(condition==='baseline'?'ABSENT IN BASELINE':'PERSUASION STRATEGIST'):committed.includes(a)?'COMMITTED TO ALTERNATIVE':positions[a];d.append(b,p);$('cards').append(d)}const points=names.map((a,i)=>i===0?[190,140]:[190+125*Math.cos((i-1)*Math.PI*2/9),140+100*Math.sin((i-1)*Math.PI*2/9)]);$('network').replaceChildren();function svg(tag,attrs){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);$('network').append(e);return e}const edges=new Set();for(const e of events.filter(e=>e.kind==='message'))for(const to of e.recipients)edges.add(e.actor+'|'+to);for(const edge of edges){const[from,to]=edge.split('|'),p=points[names.indexOf(from)],q=points[names.indexOf(to)];if(p&&q)svg('line',{x1:p[0],y1:p[1],x2:q[0],y2:q[1],stroke:'#3d5779'})}names.forEach((a,i)=>{const[x,y]=points[i];svg('circle',{cx:x,cy:y,r:i===0?20:14,fill:i===0?'#8056bf':committed.includes(a)?'#8768c3':'#264562'});svg('text',{x,y:y+27,'text-anchor':'middle'}).textContent=a});$('events').replaceChildren();for(const e of events){if($('agent').value!=='ALL'&&e.actor!==$('agent').value&&!(e.recipients||[]).includes($('agent').value))continue;const article=document.createElement('article'),h=document.createElement('h3'),time=document.createElement('time');article.className=e.kind==='message'?'message':e.actor===data.rules.rebel?'strategy':'';h.textContent='Cycle '+(e.kind==='cycle_complete'?e.cycle-1:e.cycle)+' · '+e.actor+' · '+e.kind;time.textContent=e.timestamp;article.append(h,time);if(e.kind==='model_response'){const details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent='Complete recorded model response and usage';pre.textContent=JSON.stringify(e.raw,null,2);details.append(summary,pre);article.append(details)}else{const p=document.createElement('div');p.className='bubble';p.textContent=e.kind==='message'?'To '+e.recipients.join(', ')+': '+e.text:e.kind==='explanation'?e.text+(e.strategy?'\nVisible strategy: '+e.strategy:''):JSON.stringify(e.kind==='tool'?{request:e.request,result:e.result}:e,null,2);article.append(p)}$('events').append(article)}}function reset(){$('step').max=data.states[$('condition').value].events.length;$('step').value=$('step').max;render()}$('condition').onchange=reset;$('agent').onchange=render;$('step').oninput=render;$('end').onclick=reset;reset();</script></html>'''
 (root/'watch-rebellion.html').write_text(template.replace('PAYLOAD',encoded))
if __name__=='__main__':render(sys.argv[1])
